  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Movie poster table with hover zoom, clickable YouTube trailers, and ML revenue status.",
  "autosize": "none",
  "width": 1340,
  "height": 26100,
  "padding": 10,
  "data": [
    {
      "name": "movies",
      "url": {
        "%context%": true,
        "%timefield%": "ingestion_time_utc",
        "index": "movie_performance_gap_v1",
        "body": {
          "size": 300,
          "_source": [
            "title",
            "poster_path",
            "youtube_trailer_url",
            "rating_consensus_score",
            "actual_final_revenue",
            "predicted_final_revenue",
            "release_date",
            "movie_lifecycle"
          ],
          "sort": [
            {
              "actual_final_revenue": {
                "order": "desc",
                "missing": "_last"
              }
            }
          ]
        }
      },
      "format": {
        "property": "hits.hits"
      },
      "transform": [
        {
          "type": "formula",
          "as": "movie",
          "expr": "datum._source.title"
        },
        {
          "type": "formula",
          "as": "poster",
          "expr": "datum._source.poster_path ? 'https://image.tmdb.org/t/p/w154' + datum._source.poster_path : ''"
        },
        {
          "type": "formula",
          "as": "trailer",
          "expr": "datum._source.youtube_trailer_url ? datum._source.youtube_trailer_url : null"
        },
        {
          "type": "formula",
          "as": "rating",
          "expr": "datum._source.rating_consensus_score == null ? 'N/A' : format(datum._source.rating_consensus_score, '.1f')"
        },
        {
          "type": "formula",
          "as": "revenue",
          "expr": "datum._source.actual_final_revenue == null ? 'N/A' : '$' + format(datum._source.actual_final_revenue, ',.0f')"
        },
        {
          "type": "formula",
          "as": "predicted_revenue",
          "expr": "(datum._source.movie_lifecycle == 'historical' && datum._source.actual_final_revenue != null && datum._source.actual_final_revenue > 0) ? 'Used for ML training' : (datum._source.predicted_final_revenue == null ? '-' : '$' + format(datum._source.predicted_final_revenue, ',.0f'))"
        },
        {
          "type": "formula",
          "as": "predicted_revenue_fill",
          "expr": "(datum._source.movie_lifecycle == 'historical' && datum._source.actual_final_revenue != null && datum._source.actual_final_revenue > 0) ? '#dc2626' : (datum._source.predicted_final_revenue == null ? '#9ca3af' : '#16a34a')"
        },
        {
          "type": "formula",
          "as": "release_date_text",
          "expr": "datum._source.release_date == null ? 'N/A' : timeFormat(toDate(datum._source.release_date), '%Y-%m-%d')"
        },
        {
          "type": "window",
          "ops": ["row_number"],
          "as": ["row"]
        }
      ]
    }
  ],
